      <div class="PRtrueCard"><div class="PRtrueLabel">3-round gross avg</div><div class="PRtrueValue">${Number.isFinite(Ss.last3Avg)?Ss.last3Avg.toFixed(1):"—"}</div><div class="PRtrueSub">actual gross</div></div>
